using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class CommonOldExclusionConfirmationDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/CommonOldExclusionConfirmation.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Common confirmation and complete collapse applications on original exclusion balls.",
        H("Common confirmation on an old complete exclusion"), Blocks(
        Describe.Lean(DescribeId.Create("full-effect-norm-bound"), DeclarationHandle.Create(Owner + "effectNormBound"),
            H("The actual full-interval dual norm maximum"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("The bound M is the maximum of the operator norm over the entire original effect interval. It is finite and attained. The auxiliary norm supplies distances and topology; it does not supply a physical inner product.")))),
        Describe.Lean(DescribeId.Create("whole-effect-maximum"), DeclarationHandle.Create(Owner + "wholeMaximum"),
            H("One effect on the entire specified set"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("wholeMaximum(G,e) is the supremum of e on all of G. On a nonempty compact G it is an attained maximum.")))),
        Describe.Lean(DescribeId.Create("common-effect-minimum"), DeclarationHandle.Create(Owner + "kappa"),
            H("Minimum before maximum"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("kappa_G(a) minimizes wholeMaximum(G,e) over the complete original confirmer fiber F_a. The same effect e is used for every point of G. Both extrema are attained. No minimax interchange is made.")))),
        Describe.Lean(DescribeId.Create("old-ball-chart"), DeclarationHandle.Create(Owner + "oldChart"),
            H("A full original chart"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("An arbitrary chart is chosen from the exact original EB3 hypothesis. No regularity of this choice is assumed.")))),
        Describe.Lean(DescribeId.Create("old-ball-center"), DeclarationHandle.Create(Owner + "oldCenter"),
            H("The old complete ball's center"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("The chosen affine chart maps zero to the old center c_p. Reflection preserves the whole ball. The main theorem proves that every symmetry center equals this point, so the center is independent of the chart.")))),
        Describe.Lean(DescribeId.Create("actual-full-zero-effects"), DeclarationHandle.Create(Owner + "fullZeroEffects"),
            H("The actual full-zero confirmer family"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("A_p is exactly the continuous-dual representation of FixedZeroObstruction.fullZeroConfirmers: an original full-interval effect confirming p and vanishing at every mixed point of the complete D_p.")))),
        Describe.Lean(DescribeId.Create("actual-fiber-distance"), DeclarationHandle.Create(Owner + "zeroFiberDistance"),
            H("Distance from a complete confirmer fiber"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("The distance is the minimum, over all e in the whole F_a, of the actual dual norm distance from e to the whole A_p. The outer minimum is attained. No specified effect or selector is part of this definition.")))),
        Describe.Lean(DescribeId.Create("complete-old-exclusion-confirmation"),
            DeclarationHandle.Create(Owner + "common_old_exclusion_confirmation"),
            H("Complete original X125.2 and X125.3"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
            Paragraph(Text("The carrier V is arbitrary finite dimensional real normed space. C is the same closed pointed generating cone, u is the same functional strictly positive on its nonzero vectors, K is all of C intersect {u=1}, P is all of ext(K), and the comparison is the minimum over all original effects confirming its first argument. Only EB3 and reciprocity on original pure pairs are assumed. In particular there is no weakPair, Inj, least-effect, noncollapse, finite extension budget, closed-pure assumption or global continuity input.")),
            Paragraph(Text("For every nonempty compact convex centrally symmetric G contained in K and every original pure a, kappa_G(a) is attained by one e in F_a at an attained maximizing point x of G, with every y in G bounded by e(x) and every competing confirmer's whole maximum bounded below by kappa. Its exact sandwich is T_a(c)<=kappa_G(a)<=2T_a(c). For every original pure a_n tending to p, with the fixed old G=D_p, kappa_G(a_n), T_a_n(c_p), and the supremum of T_a_n(x) over every mixed x in G all tend to zero.")),
            Paragraph(Text("At every index, kappa_G(a_n)<=M d_H(D_a_n,G), which in particular gives the requested quantitative bound when the actual whole balls converge to G. If the actual entire D_a_n converge to a singleton {q}, the theorem proves q belongs to P intersect G. Eventually a single e_n in F_a_n simultaneously satisfies max_G e_n<=M(norm(a_n-p)+d_H(D_a_n,{q})) and e_n(c_p)<=M/2 times the same sum. These are eventual quantifiers, the old center, both exact constants, and the same actual effect for all mixed inputs.")),
            Paragraph(Text("The single-effect estimate chooses an actual minimizer at the old pure antipode r of q. Pure PR and a fixed original confirmer at r give T_a_n(r)<=M norm(a_n-p). Once this is below one, original normalized_effect proves that every such minimizer has a zero in K: otherwise subtract its positive attained minimum times u and normalize to obtain a strictly smaller original confirmer value. The zero lies in D_a_n, so the actual Hausdorff singleton distance bounds its distance to q. The effect norm bounds e_n(q); the antipodal sum gives twice e_n(c_p)=e_n(q)+e_n(r), and reflection bounds every old mixed input by twice the same center value. The zero set of this effect is never identified with D_a_n.")),
            Paragraph(Text("Compactness of the hyperspace of nonempty compact subsets of K supplies a converging subsubsequence of the actual complete exclusions inside every subsequence. The exact PR-domain whole-ball or pure-singleton alternative exhausts those limits. The preceding same-effect estimates force kappa to zero in both branches. Positivity and the attained common effect then bound the center value and the entire mixed-input supremum by kappa. No mixed-state PR and no affine comparison function is used.")),
            Paragraph(Text("A_p is nonempty, compact, convex, exposed in F_p, and proper. It is exactly {e in F_p:e(c_p)=0}. Every member has actual zero set in K equal to the entire D_p, directly from the full original confirmer and exclusion definitions. No Inj-dependent full_zero_faces package is used. Evaluation at c_p exposes the face, and u belongs to F_p with value one there, proving properness.")),
            Paragraph(Text("For every Hausdorff limit F_a_n to A of the whole confirmer fibers, A is contained in F_p and A meets A_p. Joint evaluation preserves the confirming equation. Effects attaining kappa have every cluster point in A_p, and a prescribed whole-fiber limit contains the same cluster point. Without selecting a fiber limit, the attained minimum dual distance from F_a_n to A_p tends to zero. The conclusions supply neither A=F_p nor A contained in A_p, convergence to a prescribed confirmer, or a continuous selection.")),
            Paragraph(Text("For an application in every original carrier, fix any original pure p0 and any of its complete three-ball charts f. In the chart domain choose coordinate unit vectors v0 and v1, put t_n=1/(n+1), and normalize v0+t_n v1 to x_n. Then x_n lies on the sphere, tends to v0, and differs from v0 at every index. The original boundary theorem and chart injectivity give original pure labels a_n=f(x_n) and p=f(v0), with a_n tending to p and a_n different from p for every n. Their original self-comparisons equal one. Applying the complete theorem to this sequence gives all three old-ball limits and the whole-fiber distance limit. This application uses arbitrary ambient V and the complete original domains; it uses no constant label sequence or extra continuity premise.")),
            Paragraph(Text("This formal result keeps all clauses of X125.2 and X125.3 together with their original prerequisite interfaces. It does not prove automatic CS, UF or NC, and makes no operational, composite, dynamical, or physical realization claim. Compactness, norm bounds, normalization, affine reflection, extrema, zero-set reduction and generic ball rigidity are reused tools; they are not independent new content or originality claims."))), DescribeRole.Theorem),
        new DocumentBlock.Section(H("Complete original collapse application: domain and correspondences"), Blocks(
            Paragraph(Text("Take any nonzero finite dimensional real space V, any closed pointed generating convex cone C, and the same linear unit u strictly positive on C minus zero. K is the entire normalized base C intersect {u=1}; P is its entire extreme locus; E is the entire original interval [0,u]. F_a contains every e in E with e(a)=1, including u, and T_a(x) is the attained minimum of e(x) over all of F_a for every mixed x in K. EB3 supplies an affine bijection from the closed Euclidean three-ball onto each entire D_a={x in K:T_a(x)=0}. PR is assumed only for two original pure endpoints. The auxiliary norm fixes topology, operator norms and Hausdorff distance, without choosing a physical inner product.")),
            Paragraph(Text("Fix an actual sequence p_i in P converging to p in P for which the entire D_(p_i) converge in Hausdorff distance to {q}; the existence of such a sequence is a condition of this application. ReciprocalPureCompactness.reciprocal_pure_compact supplies compactness of P from the original cone hypotheses and pure PR alone. ReciprocalExclusionLimits.exclusion_limit_dichotomy applies to the actual whole NonemptyCompacts sets: every limit is either the entire D_p or an original pure singleton in D_p. Since D_p is an injective affine image of a three-ball, it is not a singleton. Thus q belongs to P intersect D_p, and q differs from p because T_p(p)=1.")),
            Paragraph(Text("Put J(p,q)={e in E:e(p)=1 and e(q)=0}, without restricting E or either endpoint. The original exclusion definition and ExclusionWidthCompactness.comparison_zero_iff give a member of J. It is a nonempty compact convex face of E: evaluation at p is bounded above by one, evaluation at q is nonnegative, and their extremal level sets are closed faces. The common_old_exclusion_confirmation theorem gives the attained finite constant M=max over e in E of norm(e), and makes every fixed T_s M-Lipschitz on the entire mixed K. These are the original maps and the same M for all labels and effects."))
        )),
        new DocumentBlock.Section(H("X126.2: the entire pure row on the fixed original edge"), Blocks(
            Paragraph(Text("For every original pure s there exists an e_s in J(p,q) with e_s(s)=T_p(s); equivalently T_p(s) is the attained minimum over the entire J(p,q). First take s different from p. ReciprocalEndpointExposure.reciprocal_endpoint_exposure supplies an original confirmer of p whose whole one-face is {p}, so T_p(s)<1. Pure PR and the fixed-first comparison Lipschitz bound give T_(p_i)(s)=T_s(p_i) tending to T_s(p)=T_p(s). Choose one tail on which all these values are below one. This permits finitely many initial indices with p_i=s and adds no distinct-label hypothesis.")),
            Paragraph(Text("At each index of this tail use ExclusionWidthCompactness.comparison_attained to choose an actual e_i in F_(p_i) attaining T_(p_i)(s). Apply the existing CommonOldExclusionConfirmation.minimizer_has_zero to this same optimizer, with a=p_i, x=s, its unchanged equality T_(p_i)(s)=e_i(s), and e_i(s)<1. Its conclusion supplies a real z_i in the entire K with e_i(z_i)=0. Hence z_i belongs to the actual D_(p_i) by its defining original exclusion witness. The whole Hausdorff collapse gives norm(z_i-q)<=delta_i tending to zero, where delta_i=d_H(D_(p_i),{q}). No independently chosen optimizing or zero effect replaces e_i. More explicitly, put d_i=dist(p_i,p) and t=T_p(s). These same strict-tail effects simultaneously satisfy 0<=1-e_i(p)<=M d_i, 0<=e_i(q)<=M delta_i, and abs(e_i(s)-t)<=M d_i. The first uses confirmation at p_i, the second the same actual zero, and the third pure PR and the fixed T_s Lipschitz estimate.")),
            Paragraph(Text("Apply ContinuousFrameSum.effects_compact and IsCompact.tendsto_subseq to the e_i. One subsequence tends in the actual continuous dual to an original effect e_s. Joint evaluation at the moving p_i gives e_s(p)=1; joint evaluation at the same moving z_i gives e_s(q)=0; evaluation at the fixed s and the preceding comparison limit give e_s(s)=T_p(s). These three equations use one subsequence and one limit effect. The construction is an application of the existing zero, compactness and evaluation interfaces, rather than the selection of an unrelated whole-zero confirmer.")),
            Paragraph(Text("For s=p choose any existing member of J(p,q): its value at p is one, which is T_p(p). This case does not use a strict tail. Finally every member of J(p,q) belongs to F_p, so its value at s is at least T_p(s). This supplies the other minimum inequality and proves attainment for every s, with the effect allowed to depend on s. The pure-row conclusion supplies neither one common optimizer for all pure s nor equality of the two lower envelopes on every mixed point of K."))
        )),
        new DocumentBlock.Section(H("The same complete ball calibration"), Blocks(
            Paragraph(Text("For an arbitrary actual complete ball H=D_a and any whole affine chart b from the closed three-ball onto H, OriginalFacePolarity.chart_boundary identifies the entire sphere with P intersect H. Fix a unit vector w and the original pure endpoint b(w), and choose an original confirmer e_w minimizing at its actual antipode b(-w). Use the existing OriginalRegularHeight.peak_formula with this chart, this proper effect and its actual value one at b(w). For every chart vector z the same effect satisfies e_w(b(z))=1-a(w)(1-inner(w,z)), where a(w)=(1-T_(b(w))(b(-w)))/2.")),
            Paragraph(Text("Every other original confirmer f of b(w) has the same peak formula, with a_f=(1-f(b(-w)))/2. Its antipodal value is at least the attained minimum, hence a_f<=a(w). For every norm(z)<=1 the factor 1-inner(w,z) is nonnegative. Consequently the same e_w minimizes at every mixed b(z) in H, and T_(b(w))(b(z))=1-a(w)+a(w)inner(w,z) on the entire closed ball. This uses peak_formula in its original proper-effect telescope; no RegularAnchor, ZeroContinuousAt, injective exclusion map or mixed PR is introduced.")),
            Paragraph(Text("For distinct unit w and w2, pure PR at b(w),b(w2) equates a(w)(1-inner(w,w2)) and a(w2)(1-inner(w,w2)). The common factor is positive by equality in Cauchy-Schwarz, so a(w)=a(w2); equal endpoints already have equal coefficients. Thus there is a unique coefficient a_H for this entire ball. The center-uniqueness conclusion of common_old_exclusion_confirmation identifies b(0) for every whole chart with the same actual center c_H. Every whole affine chart preserves antipodes, so the coefficient is intrinsically (1-T_x(2c_H-x))/2 for any pure x in H and is independent of the chart. Strict original endpoint exposure at the distinct antipode gives a_H>0, and nonnegativity of the antipodal comparison gives a_H<=1/2. The result is T_(b(w))(b(z))=1-a_H+a_H inner(w,z) for every sphere w and every closed-ball z. Only this calibrated comparison, rather than a separate positive-extension budget theorem, is needed below."))
        )),
        new DocumentBlock.Section(H("X126.3: one actual effect for each entire mixed ball"), Blocks(
            Paragraph(Text("Let H be any actual complete ball containing p. The original boundary identification gives p=b_H(w) with norm(w)=1 and makes r_H=b_H(-w) an actual original pure point. Apply the whole pure-row conclusion at r_H to obtain one e_H in J(p,q) with e_H(r_H)=T_p(r_H). The calibrated comparison on H is affine. The affine difference d(z)=e_H(b_H(z))-[1-a_H+a_H inner(w,z)] is nonnegative on the entire closed ball, and vanishes at both w and -w. Its value at zero is therefore zero. WholePairBallConfirmation.affine_riesz and affine_nonneg_bound force its slope to vanish, so e_H(x)=T_p(x) for every mixed x in H. The choice is one effect per whole H; distinct balls may have distinct effects.")),
            Paragraph(Text("Complement symmetry of the original exclusion witness gives p in D_q. In the particular whole H=D_q write p=b_H(w), r=b_H(-w), and use the preceding e_H. Put h=u-e_H. This is an original effect in J(q,p), and on every norm(z)<=1 it has h(b_H(z))=a_H(1-inner(w,z)). The exact triples are (h(q),h(p),h(r))=(1,0,2a_H) and (e_H(p),e_H(q),e_H(r))=(1,0,1-2a_H). Here a_H is a_(D_q), irrespective of the coefficient on D_p.")),
            Paragraph(Text("If x is any mixed point of K with h(x)=0, the fact that h confirms q first places x in the entire D_q through the original exclusion definition. Write x=b_H(z), norm(z)<=1. Since a_H>0, the formula gives inner(w,z)=1; equality in the unit-ball Cauchy-Schwarz bound gives z=w and hence x=p. Conversely h(p)=0. Thus the zero set on all of K is exactly {p}. For every k in the entire J(q,p), the complement u-k lies in J(p,q), giving 1-k(r)>=T_p(r)=1-2a_H. Hence k(r)<=2a_H, and this same h attains equality: max over k in J(q,p) of k(r)=2a_(D_q)."))
        )),
        new DocumentBlock.Section(H("X126.4: every moving confirmer with its own unchanged minimum"), Blocks(
            Paragraph(Text("Fix the same old whole G=D_p=b(closedBall(0,1)) and write q=b(v) with norm(v)=1, as supplied by q in P intersect D_p and the original boundary theorem. For every index i and every f in the entire F_(p_i), let m=min over the entire K of f. Compactness attains m, and original effect bounds give 0<=m<=1 with maximum one at p_i. The affine_riesz representation of (f-mu) composed with b gives the unique alpha and vector t satisfying (f-mu)(b(z))=alpha+inner(t,z) for every chart vector z. In particular alpha=f(b(0))-m. Uniqueness follows by evaluating at zero and the coordinate directions; the parameters always belong to this same f.")),
            Paragraph(Text("If m=1 then f is one on K, so f=u on V because the entire K spans V for the original generating cone. Thus alpha=0 and t=0. This retains the actual constant confirmer u. If m<1, choose an actual minimizer z_i of this f on K. OriginalWidthContact.normalized_effect, with this minimizer and the actual maximum p_i, makes (f-mu)/(1-m) an original proper effect. It confirms p_i and is zero at this same z_i. Therefore z_i belongs to D_(p_i), while f(z_i)=m remains unchanged. This normalization does not claim m=0 for f, and does not replace f in any norm estimate.")),
            Paragraph(Text("The whole exclusion and singleton are nonempty bounded sets, so Metric.hausdorffEDist_ne_top_of_nonempty_of_bounded supplies the finite-distance premise of Metric.infDist_le_hausdorffDist_of_mem. Metric.infDist_singleton then gives norm(q-z_i)<=delta_i for the same actual minimizer. The entire original norm bound now gives 0<=f(q)-m=f(q)-f(z_i)<=norm(f) norm(q-z_i)<=M delta_i. In the case m=1 the same inequality is zero<=0<=M delta_i. No reciprocal factor 1/(1-m) occurs in the final estimate. On the entire old ball, nonnegativity of f-mu gives norm(t)<=alpha by affine_nonneg_bound; nonnegativity of (1-m)u-(f-mu) gives alpha+norm(t)<=1-m. Hence 0<=norm(t)<=alpha<=1 and 0<=alpha+inner(t,v)<=M delta_i.")),
            Paragraph(Text("Using norm(v)=1, expand norm(t+alpha v)^2=norm(t)^2+2alpha inner(t,v)+alpha^2. Since norm(t)<=alpha and 0<=alpha<=1, this is at most 2alpha(alpha+inner(t,v)), and hence at most 2M delta_i. For every norm(z)<=1, the exact residual f(b(z))-[m+alpha(1-inner(v,z))] equals inner(t+alpha v,z). Cauchy-Schwarz bounds its absolute value by norm(t+alpha v)<=sqrt(2M delta_i). The original f, its own m and its own alpha occur on both sides.")),
            Paragraph(Text("The right side is the same for every f in the whole F_(p_i) and every mixed z of the entire old closed ball. Both indexing sets are nonempty, and the pointwise bound bounds their nonnegative residuals, so the nested supremum over all f and all norm(z)<=1 is at most sqrt(2M delta_i). Every index is included; only the pure-row optimizer construction used an eventual strict tail. These estimates require no regularity of chosen charts, no least confirmer, and no pure-only replacement of the moving effect face."))
        )),
        new DocumentBlock.Section(H("The entire moving-face inclusion and the remaining scope"), Blocks(
            Paragraph(Text("For any actual Hausdorff limit A of the entire compact faces F_(p_i), recover an approximating sequence for every f in A with FixedZeroObstruction.recover_limit. Joint evaluation puts f in F_p, so A is contained in the entire F_p, and the common confirmation theorem also gives a member of A intersect A_p. The stronger collapse estimate above applies to every recovered effect, including u. The actual minima converge to m_f=min_K f because norm convergence of effects is uniform on the bounded whole K. Chart evaluation determines converging alpha and t, and delta_i tends to zero. Thus A is contained in the set of all f in F_p with f(q)=m_f and f(b(z))=m_f+alpha_f(1-inner(v,z)) on all of the old ball, where alpha_f=f(b(0))-m_f and 0<=2alpha_f<=1-m_f. This is an inclusion for the full face, rather than for selected minimizers; it permits the unchanged constant effect u with m_f=1 and alpha_f=0.")),
            Paragraph(Text("In particular, any convergent old-ball slopes of actual moving confirmers lie in the nonpositive ray through v. Two nonzero limiting slopes outside the same ray exclude this particular collapse only when both originating effects really confirm the same moving p_i. Positive extension alone does not supply that confirming equation. The application keeps all clauses of X126.2, X126.3 and X126.4 in the original arbitrary-dimensional model. It does not establish the existence of a collapse, automatic CS, UF or NC, a mixed-state reciprocity law, a single effect for all complete balls, the separate X126.5 positive-family budget formulas, or the stronger X126.6 and X126.7 branch. The mathematical consequences here make no claim of literature priority or physical realization."))
        ))
        )));
}
